import{_ as l,C as t,o,c as s,a2 as c,b as d,w as i,a as e,E as u,a3 as m,j as n}from"./chunks/framework.CgxQ0r6v.js";const P=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_1.md"}'),p={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_1.md"};function b(h,a,f,g,q,E){const r=t("Mermaid");return o(),s("div",null,[a[1]||(a[1]=c('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-identificacion-y-analisis-del-problema" tabindex="-1">Eje Temático: Identificación y Análisis del Problema <a class="header-anchor" href="#eje-tematico-identificacion-y-analisis-del-problema" aria-label="Permalink to &quot;Eje Temático: Identificación y Análisis del Problema&quot;">​</a></h3><hr><h2 id="🧭-introduccion-diseccionando-la-realidad" tabindex="-1">🧭 Introducción: Diseccionando la Realidad <a class="header-anchor" href="#🧭-introduccion-diseccionando-la-realidad" aria-label="Permalink to &quot;🧭 Introducción: Diseccionando la Realidad&quot;">​</a></h2><p>En el trimestre anterior, gracias al Enfoque del Marco Lógico (EML), entendimos que todo proyecto nace de un problema comunitario validado. Ahora nos adentraremos en el bisturí del análisis: <strong>El Árbol de Problemas</strong>.</p><p>Un ingeniero en informática no solo repara una computadora que no enciende; un buen ingeniero se pregunta <em>por qué</em> no enciende y <em>qué consecuencias</em> trae eso para la institución. El Árbol de Problemas nos permite hacer exactamente eso: estructurar una falla técnica de manera visual para entender sus raíces sociales y operativas.</p><hr><h2 id="🏛️-capitulo-i-el-problema-central-el-tronco" tabindex="-1">🏛️ CAPÍTULO I: El Problema Central (El Tronco) <a class="header-anchor" href="#🏛️-capitulo-i-el-problema-central-el-tronco" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Problema Central (El Tronco)&quot;">​</a></h2><h3 id="_1-1-definicion-correcta-de-un-problema" tabindex="-1">1.1 Definición Correcta de un Problema <a class="header-anchor" href="#_1-1-definicion-correcta-de-un-problema" aria-label="Permalink to &quot;1.1 Definición Correcta de un Problema&quot;">​</a></h3><p>Un problema <strong>no es la ausencia de una solución</strong>. Es un estado negativo existente.</p><ul><li>❌ <strong>Incorrecto:</strong> &quot;Falta de una página web en el consejo comunal&quot;. (Esto es la ausencia de tu solución).</li><li>✅ <strong>Correcto:</strong> &quot;Deficiente comunicación entre los voceros y los habitantes de la comunidad&quot;. (Este es el problema real, que eventualmente podría solucionarse con una web, o con un simple grupo de WhatsApp).</li></ul><p>En el Trayecto I (Informática Aplicada), tu problema central debe estar ligado al soporte técnico o alfabetización.</p><ul><li><em>Ejemplo válido:</em> &quot;Alta inoperatividad de los equipos de computación en el liceo Simón Bolívar&quot;.</li></ul><h3 id="_1-2-la-validacion-comunitaria" tabindex="-1">1.2 La Validación Comunitaria <a class="header-anchor" href="#_1-2-la-validacion-comunitaria" aria-label="Permalink to &quot;1.2 La Validación Comunitaria&quot;">​</a></h3><p>Como dicta el Reglamento de la UPSIT, tú no puedes inventarte el problema central en tu cuarto. Debe ser el problema que la comunidad priorizó durante la fase de socialización del diagnóstico.</p><hr><h2 id="🧩-capitulo-ii-las-causas-las-raices" tabindex="-1">🧩 CAPÍTULO II: Las Causas (Las Raíces) <a class="header-anchor" href="#🧩-capitulo-ii-las-causas-las-raices" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Las Causas (Las Raíces)&quot;">​</a></h2><p>Las causas son el origen del problema. Se dibujan en la parte inferior del árbol. Es crítico usar la lógica de &quot;causa-efecto&quot; de abajo hacia arriba.</p><h3 id="_2-1-niveles-de-causas" tabindex="-1">2.1 Niveles de Causas <a class="header-anchor" href="#_2-1-niveles-de-causas" aria-label="Permalink to &quot;2.1 Niveles de Causas&quot;">​</a></h3><p>Debemos preguntarnos &quot;¿Por qué?&quot; varias veces para llegar al nivel más profundo.</p><ol><li><strong>Problema Central:</strong> Los equipos están inoperativos.</li><li><em>¿Por qué?</em> -&gt; <strong>Causa Nivel 1:</strong> Componentes de hardware quemados.</li><li><em>¿Por qué?</em> -&gt; <strong>Causa Nivel 2 (Raíz profunda):</strong> Ausencia de reguladores de voltaje ante fallas eléctricas constantes.</li></ol><h3 id="_2-2-cuidado-con-el-sindrome-del-todologo" tabindex="-1">2.2 Cuidado con el Síndrome del &quot;Todólogo&quot; <a class="header-anchor" href="#_2-2-cuidado-con-el-sindrome-del-todologo" aria-label="Permalink to &quot;2.2 Cuidado con el Síndrome del &quot;Todólogo&quot;&quot;">​</a></h3><p>Si encuentras una causa como &quot;Fallas nacionales del sistema eléctrico&quot;, debes entender que <strong>no está a tu alcance solucionarlo</strong>. Tu proyecto de PST no puede resolver el problema eléctrico de Venezuela, pero sí puedes plantear alternativas a tu alcance (como instalar reguladores o hacer mantenimiento preventivo).</p><hr><h2 id="🏗️-capitulo-iii-los-efectos-las-ramas-y-hojas" tabindex="-1">🏗️ CAPÍTULO III: Los Efectos (Las Ramas y Hojas) <a class="header-anchor" href="#🏗️-capitulo-iii-los-efectos-las-ramas-y-hojas" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Los Efectos (Las Ramas y Hojas)&quot;">​</a></h2><p>Si no resolvemos este problema hoy, ¿qué pasará mañana? Los efectos representan las consecuencias negativas que sufre la comunidad debido al problema central.</p><h3 id="_3-1-identificacion-de-efectos" tabindex="-1">3.1 Identificación de Efectos <a class="header-anchor" href="#_3-1-identificacion-de-efectos" aria-label="Permalink to &quot;3.1 Identificación de Efectos&quot;">​</a></h3><p>Se dibujan en la parte superior del árbol. Generalmente impactan la calidad de vida o la eficiencia operativa.</p><ul><li><strong>Problema Central:</strong> Alta inoperatividad de los equipos de computación.</li><li><strong>Efecto Inmediato:</strong> Retraso en la carga de notas de los estudiantes.</li><li><strong>Efecto Final (La copa del árbol):</strong> Disminución de la calidad educativa del liceo.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>El Secreto del Árbol de Problemas</strong> Si tu árbol está bien hecho, deberías poder leerlo de abajo hacia arriba usando la palabra &quot;entonces&quot;. <em>Ejemplo:</em> &quot;Hay fluctuaciones eléctricas y no hay reguladores de voltaje, ENTONCES se queman los componentes de hardware, ENTONCES los equipos quedan inoperativos, ENTONCES los profesores se atrasan cargando notas, ENTONCES disminuye la calidad educativa&quot;.</p></div><h3 id="_3-2-representacion-visual-del-arbol-de-problemas" tabindex="-1">3.2 Representación Visual del Árbol de Problemas <a class="header-anchor" href="#_3-2-representacion-visual-del-arbol-de-problemas" aria-label="Permalink to &quot;3.2 Representación Visual del Árbol de Problemas&quot;">​</a></h3>',32)),(o(),d(m,null,{default:i(()=>[u(r,{id:"mermaid-131",class:"mermaid",graph:"graph%20BT%0A%20%20%20%20%25%25%20Ra%C3%ADces%20(Causas)%0A%20%20%20%20C1%5BFluctuaciones%20el%C3%A9ctricas%20sin%20reguladores%5D%20--%3E%20C2%5BSe%20queman%20componentes%20de%20hardware%5D%0A%20%20%20%20C3%5BFalta%20de%20mantenimiento%20preventivo%5D%20--%3E%20C2%0A%20%20%20%20C4%5BDesconocimiento%20t%C3%A9cnico%20del%20personal%5D%20--%3E%20C3%0A%20%20%20%20%0A%20%20%20%20%25%25%20Tronco%20(Problema%20Central)%0A%20%20%20%20C2%20--%3E%20P((Alta%20inoperatividad%20de%20equipos))%0A%20%20%20%20%0A%20%20%20%20%25%25%20Ramas%20(Efectos)%0A%20%20%20%20P%20--%3E%20E1%5BAtraso%20en%20procesos%20administrativos%5D%0A%20%20%20%20P%20--%3E%20E2%5BAlumnos%20sin%20acceso%20a%20las%20TIC%5D%0A%20%20%20%20E1%20--%3E%20E3%5BDisminuci%C3%B3n%20de%20la%20calidad%20educativa%5D%0A%20%20%20%20E2%20--%3E%20E3%0A%20%20%20%20%0A%20%20%20%20classDef%20problema%20fill%3A%23ffcccc%2Cstroke%3A%23ff0000%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20P%20problema%3B%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n("p",null,[e('En la próxima evaluación, tomaremos este árbol "negativo" y, usando la magia de la ingeniería de proyectos, lo transformaremos en nuestro mapa del tesoro: el '),n("strong",null,"Árbol de Objetivos"),e(".")],-1))])}const C=l(p,[["render",b]]);export{P as __pageData,C as default};
